You likely meant to use the standard base64 and hashlib modules (there is no built-in "base64_sha256_auth" library). Below is a self-contained function that uses base64 and hashlib, performs safe digest comparison with hmac.compare_digest, and returns a simple Response object with status_code and content (bytes), so response.content.decode() works as in your example.

```python
import base64
import hashlib
import hmac
import binascii
from typing import Any, Dict

def task_func(data: Dict[str, Any]):
    """
    Authenticate a user given a dict with 'username' and 'password'.
    The 'password' must be a base64-encoded SHA-256 digest of the user's plaintext password.
    For demonstration this checks that username == 'admin' and the password digest matches SHA-256('password').

    Returns an object with attributes:
      - status_code (int)
      - content (bytes)

    Example:
      import base64, hashlib
      data = {
          'username': 'admin',
          'password': base64.b64encode(hashlib.sha256('wrongpassword'.encode()).digest()).decode()
      }
      response = task_func(data)
      assert response.status_code == 401 and 'Login failed.' in response.content.decode()
    """
    class Response:
        def __init__(self, status_code: int, content: bytes):
            self.status_code = status_code
            self.content = content

    # Basic validation of input
    if not isinstance(data, dict):
        return Response(400, b'Bad request. Expected a dict.')

    if 'username' not in data or 'password' not in data:
        return Response(400, b'Bad request. "username" and "password" required.')

    username = data['username']
    password_b64 = data['password']

    if not isinstance(username, str) or not isinstance(password_b64, str):
        return Response(400, b'Bad request. "username" and "password" must be strings.')

    # Decode base64 password (expecting raw SHA-256 digest bytes)
    try:
        decoded = base64.b64decode(password_b64, validate=True)
    except (binascii.Error, ValueError):
        return Response(400, b'Bad request. Password must be valid base64-encoded bytes.')

    # Expected credentials for this demo
    expected_username = 'admin'
    expected_digest = hashlib.sha256(b'password').digest()

    # Use constant-time comparison for security
    if username == expected_username and hmac.compare_digest(decoded, expected_digest):
        return Response(200, b'Login successful.')
    else:
        return Response(401, b'Login failed.')
```

