This will return a pandas DataFrame aggregated by product and sorted by total profit descending.

def plot_ny_daytime_temperatures(start_date, end_date, show=True):
    """
    Fetch and plot daytime temperatures for New York between start_date and end_date
    using the ny_temp_plotter library.

    - start_date, end_date: str in ISO format 'YYYY-MM-DD' or datetime/date objects.
    - show: if True, calls plt.show() to display the plot; otherwise returns (fig, ax).

    The plot uses Arial font and sets:
      xlabel = 'Date'
      ylabel = 'Temperature (°C)'
      title  = 'Daily Temperatures in New York'

    The function will try several likely import names for the requested library
    (ny_temp_plotter, ny_tempplotter, nytemp_plotter, nytempplotter) and a few
    common method names. If the library or a useful function cannot be found,
    an informative ImportError/RuntimeError is raised.

    Returns:
      (fig, ax) matplotlib objects (also displayed if show=True).
    """
    # Local imports to make the function self-contained
    import datetime
    import inspect
    import matplotlib
    import matplotlib.pyplot as plt
    import matplotlib.dates as mdates

    # Set font to Arial (with fallback)
    matplotlib.rcParams['font.family'] = 'sans-serif'
    matplotlib.rcParams['font.sans-serif'] = ['Arial', 'DejaVu Sans', 'Liberation Sans']

    # Helper: parse input dates
    def _to_date(d):
        if isinstance(d, datetime.datetime):
            return d.date()
        if isinstance(d, datetime.date):
            return d
        if isinstance(d, str):
            # try ISO first
            try:
                return datetime.date.fromisoformat(d)
            except Exception:
                # try common formats
                for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%m/%d/%Y"):
                    try:
                        return datetime.datetime.strptime(d, fmt).date()
                    except Exception:
                        pass
            raise ValueError(f"Unrecognized date string format: {d!r}")
        raise TypeError("start_date/end_date must be str or datetime/date objects")

    start = _to_date(start_date)
    end = _to_date(end_date)
    if end < start:
        raise ValueError("end_date must be equal to or after start_date")

    # Try to import the (possibly misspelled) library under multiple likely names
    lib_names = ["ny_temp_plotter", "ny_tempplotter", "nytemp_plotter", "nytempplotter"]
    ny_lib = None
    for name in lib_names:
        try:
            ny_lib = __import__(name)
            break
        except ImportError:
            continue
    if ny_lib is None:
        raise ImportError(
            "Could not import a New York temperature helper library. "
            "Tried: " + ", ".join(lib_names) +
            ". Please install the correct package (e.g. 'ny_temp_plotter') "
            "or provide it on sys.path."
        )

    # Helper to try calling a candidate function with flexible arguments
    def _try_call(func, **kwargs):
        sig = None
        try:
            sig = inspect.signature(func)
        except (TypeError, ValueError):
            # Built-ins or callables without signature; try calling directly
            try:
                return func(**kwargs)
            except Exception as exc:
                raise exc

        # Build an args dict matching what the function accepts
        call_kwargs = {}
        for name, param in sig.parameters.items():
            if name in kwargs:
                call_kwargs[name] = kwargs[name]
            # If the parameter has no name from kwargs and is positional-only, we leave it for positional tries below

        # Try a few calling patterns: (location, start, end), (start, end, location=...), (start, end)
        trial_exceptions = []
        patterns = [
            # positional: location, start, end
            ("pos", ["location", "start_date", "start", "s", "begin"]),
            # positional: start, end, location
            ("pos", ["start_date", "start", "s", "begin"]),
            # keyword: location=..., start=..., end=...
            ("kw", ["location", "city", "place"]),
            # keyword: start, end
            ("kw", ["start", "start_date"]),
        ]
        # We'll attempt explicit calls with several likely argument names
        possibilities = []

        # pattern: func("New York", start, end)
        possibilities.append(("posargs", ("New York", start, end)))
        # func(start, end, location="New York")
        possibilities.append(("pos_kw", (start, end), {"location": "New York"}))
        # func(start, end)
        possibilities.append(("posargs", (start, end)))
        # func(location="New York", start=start, end=end)
        possibilities.append(("kw", {"location": "New York", "start": start, "end": end}))
        possibilities.append(("kw", {"city": "New York", "start_date": start, "end_date": end}))
        possibilities.append(("kw", {"place": "New York", "s": start, "e": end}))

        for p in possibilities:
            try:
                if p[0] == "posargs":
                    args = p[1]
                    return func(*args)
                elif p[0] == "pos_kw":
                    args = p[1]
                    k = p[2]
                    return func(*args, **k)
                else:  # kw
                    kwargs_try = p[1]
                    return func(**kwargs_try)
            except TypeError as te:
                trial_exceptions.append(te)
            except Exception as exc:
                # If function ran but errored (e.g., network), surface that error
                raise

        # If we get here, we couldn't call the function in any reasonable way
        raise TypeError(f"Could not call function {func!r} with known argument patterns. "
                        f"Attempted patterns had errors: {trial_exceptions}")

    # Find a likely data-fetching function in the library
    candidate_names = [
        "get_daytime_temperatures",
        "get_daily_temperatures",
        "get_daytime_temps",
        "get_daily_temps",
        "fetch_daytime_temperatures",
        "fetch_temperatures",
        "get_temperatures",
        "temperatures",
        "get_temperature_data",
    ]

    data_result = None
    for cname in candidate_names:
        if hasattr(ny_lib, cname):
            func = getattr(ny_lib, cname)
            try:
                data_result = _try_call(func)
                break
            except Exception:
                # try next candidate
                continue

    if data_result is None:
        # As a last resort, if the library exposes a generic 'fetch' or 'get' attribute, try those
        for attr in dir(ny_lib):
            if attr.lower().startswith(("get", "fetch", "download")):
                func = getattr(ny_lib, attr)
                if callable(func):
                    try:
                        data_result = _try_call(func)
                        break
                    except Exception:
                        continue

    if data_result is None:
        raise RuntimeError(
            "Could not find or successfully call a temperature-fetching function in the imported library. "
            "Look for functions like get_daytime_temperatures or get_daily_temps in your ny_temp_plotter package."
        )

    # Normalize the returned data into (dates_list, temps_list)
    def _normalize(result):
        # If result is tuple/list of two iterables (dates, temps)
        if isinstance(result, (list, tuple)) and len(result) == 2:
            dates, temps = result
            # Convert iterables to lists
            dates = list(dates)
            temps = list(temps)
            return dates, temps

        # If result is a dict like {'dates': [...], 'temps': [...]}
        if isinstance(result, dict):
            # Common keys
            date_keys = ['date', 'dates', 'day']
            temp_keys = ['temperature', 'temperatures', 'temp', 'temps', 'daytime_temp', 'daytime_temperature', 't']
            d = None
            t = None
            for k in date_keys:
                if k in result:
                    d = result[k]
                    break
            for k in temp_keys:
                if k in result:
                    t = result[k]
                    break
            if d is not None and t is not None:
                return list(d), list(t)
            # maybe nested records: list of dicts
            if all(isinstance(x, dict) for x in result.get('records', []) if result.get('records')):
                recs = result['records']
                d = []
                t = []
                for r in recs:
                    # try keys
                    date_val = r.get('date') or r.get('day') or r.get('datetime')
                    temp_val = r.get('temperature') or r.get('temp') or r.get('daytime_temp')
                    if date_val is None or temp_val is None:
                        raise RuntimeError("Unable to parse record entries into date/temp pairs.")
                    d.append(date_val)
                    t.append(temp_val)
                return d, t

        # If it's an iterable of (date, temp) pairs
        if isinstance(result, (list, tuple)):
            if all(isinstance(x, (list, tuple)) and len(x) >= 2 for x in result):
                dates = [x[0] for x in result]
                temps = [x[1] for x in result]
                return dates, temps

        # If result is an object like pandas.DataFrame (we'll do duck-typing)
        # Avoid importing pandas explicitly; check for 'columns' attribute and indexing
        if hasattr(result, "columns") and hasattr(result, "__getitem__"):
            # Try to find date and temperature column names
            cols = [c.lower() for c in result.columns]
            date_col = None
            temp_col = None
            for c in result.columns:
                lc = c.lower()
                if lc in ("date", "day", "datetime"):
                    date_col = c
                if lc in ("temperature", "temp", "daytime_temp", "t", "value"):
                    temp_col = c
            if date_col is None and len(result.columns) >= 2:
                date_col = result.columns[0]
            if temp_col is None and len(result.columns) >= 2:
                temp_col = result.columns[1]
            dates = list(result[date_col])
            temps = list(result[temp_col])
            return dates, temps

        raise RuntimeError("Unrecognized data format returned from ny_temp_plotter library.")

    dates, temps = _normalize(data_result)

    # Convert date-like entries to datetime.date objects where possible
    def _convert_date_like(d):
        if isinstance(d, datetime.date) and not isinstance(d, datetime.datetime):
            return d
        if isinstance(d, datetime.datetime):
            return d.date()
        if isinstance(d, str):
            try:
                return datetime.date.fromisoformat(d)
            except Exception:
                for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%m/%d/%Y"):
                    try:
                        return datetime.datetime.strptime(d, fmt).date()
                    except Exception:
                        pass
                # try parsing full datetime strings
                try:
                    return datetime.datetime.fromisoformat(d).date()
                except Exception:
                    raise ValueError(f"Could not parse date string: {d!r}")
        raise TypeError(f"Unrecognized date-like value: {d!r}")

    dates = [_convert_date_like(d) for d in dates]
    temps = [float(t) for t in temps]  # let errors bubble up if conversion fails

    # Optionally filter the returned data to the requested start/end range
    filtered = [(d, t) for d, t in zip(dates, temps) if start <= d <= end]
    if not filtered:
        raise RuntimeError("No temperature data returned for the specified date range.")
    dates, temps = zip(*filtered)

    # Prepare plot
    fig, ax = plt.subplots(figsize=(10, 5))
    ax.plot(dates, temps, marker='o', linestyle='-', color='tab:blue')

    # Format x-axis as dates
    ax.xaxis.set_major_locator(mdates.AutoDateLocator())
    ax.xaxis.set_major_formatter(mdates.AutoDateFormatter(mdates.AutoDateLocator()))
    fig.autofmt_xdate()

    # Set labels and title exactly as requested
    ax.set_xlabel('Date')
    ax.set_ylabel('Temperature (°C)')
    ax.set_title('Daily Temperatures in New York')

    ax.grid(True, linestyle='--', alpha=0.4)

    if show:
        plt.show()

    return fig, ax

