def compute_nested_list_stats(data, size=5, seed=None):
    """
    Compute mean, median, and mode for each sublist in `data` (a list of lists).
    If a sublist is empty, it will be filled with `size` random integers from 0..100
    (inclusive) before computing statistics.

    Tries to use an external library named 'nested_list_stats' (or a couple of likely variants).
    If that library is unavailable or doesn't provide the expected functions, falls back to
    Python's built-in `statistics` module.

    Parameters:
    - data: list of lists of numbers (ints or floats)
    - size: number of random integers to insert for empty sublists (default 5)
    - seed: optional int seed for reproducible random filling (default None)

    Returns: a list of dicts, one per sublist, with keys:
      - 'values': the list of numbers used (a copy; empty lists are replaced)
      - 'mean': arithmetic mean (float)
      - 'median': median (float or int)
      - 'mode': single mode value if unique mode, otherwise a list of mode values
    """
    import importlib
    import random
    import statistics
    import copy
    import warnings
    from numbers import Number

    # Defensive copy of input to avoid mutating caller data
    if not isinstance(data, list):
        raise TypeError("data must be a list of lists")
    working = [copy.copy(inner) if isinstance(inner, list) else inner for inner in data]

    # Set random seed if provided
    if seed is not None:
        random.seed(seed)

    # Try to import possible library names (fixing user mistakes)
    candidate_names = [
        "nested_list_stats",
        "nested_list_statistics",
        "nestedliststats",
        "nestedlists_stats",
    ]
    external_mod = None
    for name in candidate_names:
        try:
            mod = importlib.import_module(name)
            external_mod = mod
            break
        except Exception:
            continue

    # Helper wrappers that prefer external_mod functions if present, else statistics.*
    def _mean(values):
        if external_mod and hasattr(external_mod, "mean"):
            try:
                return external_mod.mean(values)
            except Exception:
                warnings.warn("external module mean() failed; falling back to statistics.mean")
        return statistics.mean(values)

    def _median(values):
        if external_mod and hasattr(external_mod, "median"):
            try:
                return external_mod.median(values)
            except Exception:
                warnings.warn("external module median() failed; falling back to statistics.median")
        return statistics.median(values)

    def _modes(values):
        # Return list of modes (one or more). Prefer multimode if available.
        if external_mod:
            if hasattr(external_mod, "multimode"):
                try:
                    return list(external_mod.multimode(values))
                except Exception:
                    warnings.warn("external module multimode() failed; falling back to statistics.multimode")
            if hasattr(external_mod, "mode"):
                try:
                    # If external mode raises on multimodal, catch and fallback.
                    m = external_mod.mode(values)
                    return [m]
                except Exception:
                    warnings.warn("external module mode() failed; falling back to statistics.multimode")
        # Default: use statistics.multimode (Python 3.8+)
        try:
            return list(statistics.multimode(values))
        except Exception:
            # As a last resort, compute modes manually
            freq = {}
            for v in values:
                freq[v] = freq.get(v, 0) + 1
            max_count = max(freq.values())
            return [v for v, c in freq.items() if c == max_count]

    results = []
    for idx, inner in enumerate(working):
        if not isinstance(inner, list):
            raise TypeError(f"element at index {idx} is not a list")

        # If empty, fill with random integers between 0 and 100 inclusive
        if len(inner) == 0:
            inner[:] = [random.randint(0, 100) for _ in range(size)]

        # Validate numeric elements
        for v in inner:
            if not isinstance(v, Number):
                raise TypeError(f"non-numeric value {v!r} found in sublist at index {idx}")

        # Convert ints to floats where appropriate? statistics.* accepts ints.
        # Compute stats
        try:
            mean_val = _mean(inner)
            median_val = _median(inner)
            modes = _modes(inner)
        except Exception as e:
            raise RuntimeError(f"failed to compute statistics for sublist at index {idx}: {e}")

        # Normalize mode: return single value if unique, else list
        mode_val = modes[0] if len(modes) == 1 else modes

        results.append({
            "values": list(inner),  # return a copy
            "mean": mean_val,
            "median": median_val,
            "mode": mode_val,
        })

    return results

