        # Determine mode for each column with tie-break by alphabetical smallest value
        result: Dict[str, str] = {}
        for field, counter in counters.items():
            if not counter:
                # No values collected (shouldn't happen if row_count > 0), skip
                continue
            # Find the max count
            max_count = max(counter.values())
            # Get all values with that count and pick alphabetically first
            tied_values = [val for val, cnt in counter.items() if cnt == max_count]
            # Python's default string sort is lexicographical; ensure deterministic ordering
            chosen = sorted(tied_values)[0]
            result[field] = chosen

