        path_parts = path.split('.')
    elif isinstance(path, Sequence) and not isinstance(path, (str, bytes)):
        path_parts = list(path)
    else:
        raise TypeError("path must be a dot-separated string or a list/sequence of keys")

    # Helper to collect numeric values from arbitrary node (flatten lists/dicts)
    def collect_numbers(node, out):
        if node is None:
            return
        if isinstance(node, Number) and not isinstance(node, bool):
            out.append(float(node))
        elif isinstance(node, Mapping):
            for v in node.values():
                collect_numbers(v, out)
        elif isinstance(node, Sequence) and not isinstance(node, (str, bytes)):
            for elem in node:
                collect_numbers(elem, out)
        # else: ignore non-numeric leaves

    # Recursive traversal following path_parts, supporting '*' wildcard on any level
    results = []

    def traverse(node, idx):
        if idx >= len(path_parts):
            # collect numeric values under this node (could be scalar, list, dict)
            collect_numbers(node, results)
            return

        key = path_parts[idx]

        if key == '*':
            # iterate all children (dict values or list elements)
            if isinstance(node, Mapping):
                for v in node.values():
                    traverse(v, idx + 1)
            elif isinstance(node, Sequence) and not isinstance(node, (str, bytes)):
                for elem in node:
                    traverse(elem, idx + 1)
            else:
                # nothing to iterate
                return
        else:
            # try to index into dict or list
            if isinstance(node, Mapping):
                if key in node:
                    traverse(node[key], idx + 1)
                else:
                    # missing key: nothing to traverse
                    return
            elif isinstance(node, Sequence) and not isinstance(node, (str, bytes)):
                # treat key as integer index if possible
                try:
                    i = int(key)
                except (ValueError, TypeError):
                    return
                # accept negative indices too
                if -len(node) <= i < len(node):
                    traverse(node[i], idx + 1)
                else:
                    return
            else:
                # node is a scalar or unknown type, cannot continue
                return

    # Start traversal
    traverse(data, 0)

    # Post-process results
    values = [float(x) for x in results if isinstance(x, Number)]

    if not values:
        raise ValueError("No numeric values found at the given path: {}".format(path))

    # Try to use jsondata_viz if it has a helper to plot (best-effort). Otherwise use matplotlib.
    fig = None
    try:
