        import matplotlib.pyplot as plt

        fig, ax = plt.subplots()
        x = list(range(len(values)))

        if chart_type == 'line':
            ax.plot(x, values, marker='o', linestyle='-')
        elif chart_type == 'bar':
            ax.bar(x, values)
        elif chart_type == 'scatter':
            ax.scatter(x, values)
        elif chart_type == 'hist':
            ax.hist(values, bins='auto')
        else:
            # unknown chart type -> default to line
            ax.plot(x, values, marker='o', linestyle='-')

        if title:
            ax.set_title(title)
        if xlabel:
            ax.set_xlabel(xlabel)
        else:
            if chart_type != 'hist':
                ax.set_xlabel('index')
        if ylabel:
            ax.set_ylabel(ylabel)
        else:
            if chart_type != 'hist':
                ax.set_ylabel('value')

        fig.tight_layout()

        if show:
            plt.show()

    return values, fig

