                content = f.read().strip()
                if content == "":
                    # empty file -> create new array
                    to_write = [record]
                else:
                    existing = json.loads(content)
                    if isinstance(existing, list):
                        existing.append(record)
                        to_write = existing
                    else:
                        # wrap existing content and new record into an array
                        to_write = [existing, record]
        except (json.JSONDecodeError, OSError):
            # If file can't be read or is invalid JSON, overwrite with a fresh array
            to_write = [record]
    else:
        to_write = [record]

    # 4) Write back to file (atomically if possible)
    tmp_filename = filename + ".tmp"
    with open(tmp_filename, "w", encoding="utf-8") as f:
        json.dump(to_write, f, ensure_ascii=False, indent=2)
        f.write("\n")
    os.replace(tmp_filename, filename)  # atomic rename on most OSes

    return record
```

