from typing import Optional, Dict, Any
from PIL import Image, ExifTags
import pytesseract

def extract_and_convert_text(
    image_path: str,
    target_encoding: str = 'utf-8',
    ocr_lang: str = 'eng',
    tesseract_cmd: Optional[str] = None,
    allow_replacement_on_encode: bool = True
) -> Dict[str, Any]:
    """
    Open an image, extract text via OCR, and convert that text to the requested encoding.
    If OCR returns nothing or encoding strictly fails, fall back to image comment/metadata.
    Returns a dict:
      {
        'source': 'ocr' or 'metadata',
        'text': <unicode str extracted>,
        'encoded': <bytes in target_encoding>,
        'encoding': <target_encoding>,
        'errors_used': <'strict' or 'replace'>
      }

    Parameters:
      image_path: path to the image file
      target_encoding: desired output byte encoding (e.g., 'utf-8', 'latin-1')
      ocr_lang: language code(s) for pytesseract (default 'eng')
      tesseract_cmd: full path to tesseract executable if needed (optional)
      allow_replacement_on_encode: if True, will try encoding with 'replace' if strict fails
    """
    # Optionally set pytesseract command path
    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    def try_encode(text: str, encoding: str, strict_first=True):
        """
        Try to encode text into bytes using given encoding.
        Returns (encoded_bytes, errors_used) or (None, None) if strict failed and replacements not allowed.
        """
        if strict_first:
            try:
                return text.encode(encoding, errors='strict'), 'strict'
            except UnicodeEncodeError:
                if allow_replacement_on_encode:
                    return text.encode(encoding, errors='replace'), 'replace'
                return None, None
        else:
            # Directly try replace
            return text.encode(encoding, errors='replace'), 'replace'

    def extract_metadata_comment(img: Image.Image) -> Optional[str]:
        """
        Try to extract image comment / description from common metadata locations:
        - JPEG EXIF UserComment / ImageDescription
        - PNG info tEXt entries (e.g., 'Comment', 'Description')
        """
        # 1) PNG and other formats: PIL stores text chunks in info dict
        info = getattr(img, 'info', {}) or {}
        # Common keys: 'comment' (bytes), 'Description', 'Comment'
        for key in ('comment', 'Comment', 'Description', 'description'):
            if key in info and info[key]:
                val = info[key]
                # comment for PNG may be bytes or str
                if isinstance(val, bytes):
                    # try common decodings
                    for enc in ('utf-8', 'utf-16', 'latin-1'):
                        try:
                            return val.decode(enc)
                        except Exception:
                            continue
                    # as fallback:
                    try:
                        return val.decode('latin-1', errors='replace')
                    except Exception:
                        pass
                else:
                    return str(val)

        # 2) EXIF (JPEG, TIFF)
        try:
            exif = img.getexif()
        except Exception:
            exif = None

        if exif:
            for tag, value in exif.items():
                name = ExifTags.TAGS.get(tag, tag)
                if name in ('UserComment', 'ImageDescription', 'XPComment', 'XPTitle'):
                    if value is None:
                        continue
                    # Some EXIF fields come as bytes, some as lists of ints (XP* in Windows)
                    if isinstance(value, bytes):
                        # Try utf-8 then latin-1
                        for enc in ('utf-8', 'utf-16', 'latin-1'):
                            try:
                                return value.decode(enc)
                            except Exception:
                                continue
                        return value.decode('latin-1', errors='replace')
                    elif isinstance(value, (list, tuple)):
                        # XP fields sometimes come as a list of ints representing UTF-16LE
                        try:
                            # Filter ints and convert
                            b = bytes([v for v in value if isinstance(v, int)])
                            return b.decode('utf-16le', errors='replace')
                        except Exception:
                            return str(value)
                    else:
                        return str(value)

        # If nothing found
        return None

    # Open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise RuntimeError(f"Cannot open image '{image_path}': {e}")

    # 1) Attempt OCR
    try:
        ocr_text = pytesseract.image_to_string(img, lang=ocr_lang)
    except pytesseract.pytesseract.TesseractNotFoundError:
        raise RuntimeError("Tesseract executable not found. Install Tesseract-OCR and/or set tesseract_cmd.")
    except Exception as e:
        # OCR failed unexpectedly; proceed to metadata fallback
        ocr_text = ''

    if ocr_text:
        ocr_text = ocr_text.strip()
    # Try to encode OCR text if non-empty
    if ocr_text:
        encoded, errors_used = try_encode(ocr_text, target_encoding, strict_first=True)
        if encoded is not None:
            return {
                'source': 'ocr',
                'text': ocr_text,
                'encoded': encoded,
                'encoding': target_encoding,
                'errors_used': errors_used
            }
        # strict failed and replacement was used (if allowed) will already have returned; otherwise continue to metadata fallback

    # 2) Fallback: try to extract metadata/comment
    comment = extract_metadata_comment(img)
    if comment:
        comment = comment.strip()
        encoded, errors_used = try_encode(comment, target_encoding, strict_first=True)
        if encoded is not None:
            return {
                'source': 'metadata',
                'text': comment,
                'encoded': encoded,
                'encoding': target_encoding,
                'errors_used': errors_used
            }
        # If strict failed, try replacement if allowed
        if allow_replacement_on_encode:
            encoded, errors_used = try_encode(comment, target_encoding, strict_first=False)
            return {
                'source': 'metadata',
                'text': comment,
                'encoded': encoded,
                'encoding': target_encoding,
                'errors_used': errors_used
            }

    # Nothing worked
    raise RuntimeError("No text could be extracted from OCR or image metadata, or encoding failed.")

# Example usage:
# result = extract_and_convert_text('example.jpg', target_encoding='latin-1')
# print(result['source'], result['encoding'], result['errors_used'])
# print(result['text'])
# print(result['encoded'])  # bytes in requested encoding
