def average_time_diff_seconds(timestamps, tz="UTC"):
    """
    Calculate the average time difference in seconds between each consecutive pair of
    timestamps in `timestamps`, after converting them to the specified timezone.

    Behavior:
    - timestamps: a list of datetime.datetime objects, ISO-8601 strings, or UNIX timestamps (int/float).
    - tz: an IANA timezone name (e.g. "Europe/London") or a tzinfo instance. Defaults to "UTC".
    - If a timestamp string has no timezone info, it is assumed to be UTC.
    - Differences are computed between consecutive items in the given list order (no sorting).
    - The absolute value of each difference is used, and the mean of those absolute differences
      (in seconds) is returned.
    - If fewer than 2 timestamps are provided, returns None.

    The function will try to use an external package named "avg_time_diff" if available;
    if not present (or if it lacks a usable entrypoint), it falls back to a robust stdlib-based
    implementation using zoneinfo (Python 3.9+) and dateutil for flexible parsing when available.
    """
    from datetime import datetime, timezone
    try:
        # zoneinfo is in the standard library on Python 3.9+
        from zoneinfo import ZoneInfo
    except Exception:
        ZoneInfo = None

    # Attempt to import the (possibly intended) external library.
    # If it exists and exposes a usable function, prefer it.
    try:
        import avg_time_diff as _atd  # user-specified library name; may not exist
    except Exception:
        _atd = None

    # If external lib provides a clear callable we can try, prefer that (best-effort).
    if _atd is not None:
        for candidate in (
            "average_time_diff_seconds",
            "avg_time_diff_seconds",
            "average_time_diff",
            "avg_time_diff",
            "compute_average_time_diff",
        ):
            func = getattr(_atd, candidate, None)
            if callable(func):
                try:
                    # Let the external function run; assume it accepts same arguments.
                    return func(timestamps, tz)
                except TypeError:
                    # Unexpected signature; skip to fallback implementation.
                    pass
                except Exception:
                    # If the external library errors for some other reason, fallback.
                    pass

    # ---------- Fallback implementation ----------
    # Helper: parse a single timestamp into an aware datetime
    def _parse_to_dt(ts):
        if isinstance(ts, datetime):
            dt = ts
        elif isinstance(ts, (int, float)):
            # treat numeric as UNIX timestamp (seconds since epoch)
            dt = datetime.fromtimestamp(ts, tz=timezone.utc)
        elif isinstance(ts, str):
            # Try dateutil first for robust parsing; fall back to fromisoformat.
            try:
                from dateutil import parser as _du_parser  # type: ignore
                dt = _du_parser.parse(ts)
            except Exception:
                # fromisoformat accepts many ISO formats but not all timezone abbreviations.
                try:
                    dt = datetime.fromisoformat(ts)
                except Exception as e:
                    raise ValueError(f"String timestamp not parseable: {ts!r}") from e
        else:
            raise TypeError(f"Unsupported timestamp type: {type(ts)}")

        # If naive, assume UTC (explicitly). This choice keeps behavior deterministic.
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt

    # Prepare timezone target tzinfo
    if isinstance(tz, str):
        if ZoneInfo is None:
            # zoneinfo not available; try pytz if present
            try:
                import pytz  # type: ignore
                target_tz = pytz.timezone(tz)
            except Exception:
                # fallback to UTC
                target_tz = timezone.utc
        else:
            try:
                target_tz = ZoneInfo(tz)
            except Exception:
                # Invalid tz name -> fallback to UTC
                target_tz = timezone.utc
    else:
        # assume tz is tzinfo-like
        target_tz = tz if tz is not None else timezone.utc

    # Convert all timestamps
    if not isinstance(timestamps, (list, tuple)):
        raise TypeError("timestamps must be a list or tuple of timestamp values")

    if len(timestamps) < 2:
        return None

    dt_list = []
    for ts in timestamps:
        dt = _parse_to_dt(ts)
        # Some tz libraries (pytz) require localize/normalize, but astimezone handles tzinfo-based objects.
        try:
            converted = dt.astimezone(target_tz)
        except Exception:
            # For pytz timezone objects, astimezone generally works, but in rare cases fallback:
            try:
                import pytz  # type: ignore
                if isinstance(target_tz, pytz.BaseTzInfo):
                    # convert by first getting UTC time then localize
                    converted = dt.astimezone(pytz.UTC).astimezone(target_tz)
                else:
                    raise
            except Exception:
                # As a last resort, keep original dt (but it is timezone-aware from earlier assumption).
                converted = dt
        dt_list.append(converted)

    # Compute absolute differences in seconds between consecutive pairs
    diffs = []
    for a, b in zip(dt_list, dt_list[1:]):
        delta = (b - a).total_seconds()
        diffs.append(abs(delta))

    if not diffs:
        return None

    avg_seconds = sum(diffs) / len(diffs)
    return float(avg_seconds)

