import os
import re
from typing import Dict, Any
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from scipy.stats import f_oneway

def analyze_csv_numerical(
    file_path: str,
    output_dir: str = None,
    show_plots: bool = False
) -> Dict[str, Any]:
    """
    Analyze numerical data in a CSV file.

    - Reads the CSV file using pandas.
    - Converts string representations of numbers (including those that use commas
      as thousand separators like "1,234.56" or as decimal separators like "1.234,56")
      into floats.
    - Computes mean and sample standard deviation (ddof=1) for each numerical column.
    - Generates and saves a histogram plot for each numerical column (to `output_dir`
      or ./histograms if not provided). Set show_plots=True to display them.
    - Performs a one-way ANOVA across numerical columns (if there are at least two
      numeric columns with enough observations), returning the F-statistic and p-value.

    Returns:
        A dictionary with:
         - 'column_stats': {col_name: {'mean': ..., 'std': ..., 'count': ..., 'histogram': path_or_none}}
         - 'anova': {'F': float, 'pvalue': float} or None if not performed
         - 'numeric_columns': list of column names treated as numeric

    Notes:
      - Uses numpy.nan semantics: missing/unparseable values are treated as NaN and ignored
        in computations.
      - Uses sample standard deviation (ddof=1). If a column has fewer than 2 non-NaN values,
        std will be returned as NaN.
    """

    def _parse_number(x):
        """Attempt to coerce a single scalar to float, handling thousand/decimal commas."""
        if x is None:
            return np.nan
        if isinstance(x, (int, float, np.integer, np.floating)):
            return float(x)
        s = str(x).strip()
        if s == '':
            return np.nan
        if s.lower() in {'na', 'n/a', 'nan', 'none'}:
            return np.nan

        # Keep only characters that might be part of a number: digits, signs, dot, comma, exponent
        s_clean = re.sub(r'[^\d\.,\-\+eE]', '', s)

        # If both '.' and ',' are present:
        #   assume comma is thousand separator (e.g., "1,234.56") -> remove commas
        if '.' in s_clean and ',' in s_clean:
            try:
                return float(s_clean.replace(',', ''))
            except ValueError:
                pass

        # If only commas are present (no dot), interpret a single comma as decimal sep (European style),
        # but if there are multiple commas it is probably thousand separators -> remove commas
        if ',' in s_clean and '.' not in s_clean:
            if s_clean.count(',') == 1:
                try:
                    return float(s_clean.replace(',', '.'))
                except ValueError:
                    pass
            else:
                # multiple commas -> remove them
                try:
                    return float(s_clean.replace(',', ''))
                except ValueError:
                    pass

        # Default: remove commas (assume they are thousand separators) and try to parse
        try:
            return float(s_clean.replace(',', ''))
        except ValueError:
            # Final fallback: try original string with comma->dot replacement
            try:
                return float(s.replace(',', '.'))
            except Exception:
                return np.nan

    # Read CSV
    df = pd.read_csv(file_path, dtype=str)  # read everything as string first to handle mixed columns

    numeric_cols = []
    column_stats = {}
    # Prepare output dir
    if output_dir is None:
        output_dir = os.path.join(os.getcwd(), "histograms")
    os.makedirs(output_dir, exist_ok=True)

    for col in df.columns:
        series = df[col]

        # Try to coerce values in this column to numeric using the parsing helper
        parsed = series.map(_parse_number)

        # Convert to numeric dtype (float) and keep NaN for unparseable items
        numeric_series = pd.to_numeric(parsed, errors='coerce')

        # Decide if this is a numeric column: at least one non-NaN value
        non_na_count = int(numeric_series.count())
        if non_na_count == 0:
            # Not a numeric column
            column_stats[col] = {
                'mean': None,
                'std': None,
                'count': 0,
                'histogram': None
            }
            continue

        numeric_cols.append(col)

        values = numeric_series.to_numpy(dtype=float)  # includes np.nan

        # Compute statistics ignoring NaNs
        mean = float(np.nanmean(values))
        # sample std (ddof=1). If count < 2, std will be NaN
        std = float(np.nanstd(values, ddof=1)) if non_na_count >= 2 else float('nan')

        # Histogram
        vals_non_na = values[~np.isnan(values)]
        plt.figure()
        plt.hist(vals_non_na, bins='auto', color='C0', edgecolor='black')
        plt.xlabel(col)
        plt.ylabel('Frequency')
        plt.title(f'Histogram of {col} (n={non_na_count})')
        hist_filename = os.path.join(output_dir, f"{re.sub(r'[^0-9a-zA-Z_\\-]', '_', col)}_hist.png")
        plt.tight_layout()
        plt.savefig(hist_filename)
        if show_plots:
            plt.show()
        plt.close()

        column_stats[col] = {
            'mean': mean,
            'std': std,
            'count': non_na_count,
            'histogram': hist_filename
        }

    # ANOVA: if at least two numeric columns with at least 2 observations each
    anova_result = None
    anova_groups = []
    for col in numeric_cols:
        cnt = column_stats[col]['count']
        if cnt >= 2:
            # Extract non-NaN values for the column
            s = pd.to_numeric(df[col].map(_parse_number), errors='coerce').dropna().astype(float)
            if len(s) >= 2:
                anova_groups.append(s.values)

    if len(anova_groups) >= 2:
        try:
            F, p = f_oneway(*anova_groups)
            anova_result = {'F': float(F), 'pvalue': float(p)}
        except Exception as e:
            anova_result = {'error': f'ANOVA failed: {e}'}
    else:
        anova_result = None

    result = {
        'column_stats': column_stats,
        'anova': anova_result,
        'numeric_columns': numeric_cols
    }

    return result
