def extract_urls_and_geolocate(text, ip_api_base="http://ip-api.com/json/", timeout=5):
    """
    Extract all URLs from `text`, determine the registered domain for each URL,
    and fetch geolocation info for each domain using the ip-api.com JSON API.

    Returns a dict:
      {
        "urls": [list of extracted URLs],
        "domains": [list of extracted registered domains in same order, deduplicated],
        "geodata": { domain: geodata_dict_or_error_info, ... }
      }

    Notes:
    - Uses urlextract to find URLs and tldextract to compute the registered domain.
    - Uses ip-api.com (http://ip-api.com/json/<domain>) for geolocation.
      Be aware of ip-api rate limits for the free tier (see ip-api docs).
    - If the ip-api response contains "status":"success", the geodata dict from ip-api
      is returned. Otherwise an error dict is returned for that domain.
    """
    # Local imports so the function is self-contained.
    try:
        from urlextract import URLExtract
    except Exception as e:
        raise ImportError("Missing dependency 'urlextract'. Install with: pip install urlextract") from e

    try:
        import tldextract
    except Exception as e:
        raise ImportError("Missing dependency 'tldextract'. Install with: pip install tldextract") from e

    try:
        import requests
    except Exception as e:
        raise ImportError("Missing dependency 'requests'. Install with: pip install requests") from e

    extractor = URLExtract()
    found_urls = extractor.find_urls(text or "")

    # Extract registered domains (e.g., example.co.uk from sub.example.co.uk)
    domains = []
    seen = set()
    for u in found_urls:
        # tldextract works with full URLs or bare hostnames
        ext = tldextract.extract(u)
        registered = ".".join(part for part in (ext.domain, ext.suffix) if part)
        if not registered:
            # fallback: try to use the raw netloc if tldextract fails
            from urllib.parse import urlparse
            parsed = urlparse(u if "://" in u else "http://" + u)
            registered = parsed.hostname or ""
        if registered and registered not in seen:
            seen.add(registered)
            domains.append(registered)

    geodata = {}
    for d in domains:
        try:
            # ip-api accepts hostnames or IPs; quote the domain to be safe
            from requests.utils import quote
            url = ip_api_base.rstrip("/") + "/" + quote(d)
            resp = requests.get(url, timeout=timeout)
            resp.raise_for_status()
            data = resp.json()
            # ip-api returns {"status":"success", ...} or {"status":"fail", "message":"..."}
            if isinstance(data, dict) and data.get("status") == "success":
                geodata[d] = data
            else:
                # include the full response as an error indicator
                geodata[d] = {"error": True, "response": data}
